package com.pdev.ekyc_service.config;

import com.pdev.ekyc_service.kafka.events.KycCompletedEvent;
import com.pdev.ekyc_service.kafka.events.KycInitiationEvent;
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.apache.kafka.common.serialization.StringSerializer;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;
import org.springframework.kafka.core.*;
import org.springframework.kafka.support.serializer.JsonDeserializer;
import org.springframework.kafka.support.serializer.JsonSerializer;
import org.springframework.kafka.core.ProducerFactory;
import org.springframework.kafka.core.DefaultKafkaProducerFactory;
import org.springframework.kafka.core.ConsumerFactory;
import org.springframework.kafka.core.DefaultKafkaConsumerFactory;
import org.springframework.kafka.support.serializer.ErrorHandlingDeserializer;

import java.util.HashMap;
import java.util.Map;

/**
 * Kafka configuration for producer and consumer.
 */
@Configuration
public class KafkaConfig {

    @Bean
    public ProducerFactory<String, KycCompletedEvent> producerFactory() {
        Map<String, Object> configProps = new HashMap<>();
        configProps.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        configProps.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class);
        configProps.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, JsonSerializer.class);

        // Configure trusted packages for the serializer
        Map<String, Object> serializerConfig = new HashMap<>();
        serializerConfig.put(JsonSerializer.ADD_TYPE_INFO_HEADERS, true);
        serializerConfig.put(JsonSerializer.TYPE_MAPPINGS, 
            "kycCompletedEvent:com.pdev.ekyc_service.kafka.events.KycCompletedEvent");

        JsonSerializer<KycCompletedEvent> jsonSerializer = new JsonSerializer<>();
        jsonSerializer.configure(serializerConfig, false);

        return new DefaultKafkaProducerFactory<>(configProps, new StringSerializer(), jsonSerializer);
    }

    @Bean
    public KafkaTemplate<String, KycCompletedEvent> kafkaTemplate() {
        return new KafkaTemplate<>(producerFactory());
    }

    @Bean
    public ConsumerFactory<String, KycInitiationEvent> consumerFactory() {
        Map<String, Object> configProps = new HashMap<>();
        configProps.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        configProps.put(ConsumerConfig.GROUP_ID_CONFIG, "ekyc-service-group");
        configProps.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);

        // Configure error handling deserializer
        configProps.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, ErrorHandlingDeserializer.class);
        configProps.put(ErrorHandlingDeserializer.VALUE_DESERIALIZER_CLASS, JsonDeserializer.class);

        // Configure trusted packages for the deserializer
        Map<String, Object> deserializerConfig = new HashMap<>();
        deserializerConfig.put(JsonDeserializer.TRUSTED_PACKAGES, "com.pdev.ekyc_service.kafka.events");
        deserializerConfig.put(JsonDeserializer.VALUE_DEFAULT_TYPE, "com.pdev.ekyc_service.kafka.events.KycInitiationEvent");
        deserializerConfig.put(JsonDeserializer.USE_TYPE_INFO_HEADERS, true);

        JsonDeserializer<KycInitiationEvent> jsonDeserializer = new JsonDeserializer<>();
        jsonDeserializer.configure(deserializerConfig, false);

        return new DefaultKafkaConsumerFactory<>(configProps, new StringDeserializer(), 
            new ErrorHandlingDeserializer<>(jsonDeserializer));
    }

    @Bean
    public ConcurrentKafkaListenerContainerFactory<String, KycInitiationEvent> kafkaListenerContainerFactory() {
        ConcurrentKafkaListenerContainerFactory<String, KycInitiationEvent> factory = new ConcurrentKafkaListenerContainerFactory<>();
        factory.setConsumerFactory(consumerFactory());
        return factory;
    }
}

package com.pdev.ekyc_service.config;

import org.springframework.context.annotation.Configuration;

/**
 * Kafka configuration for producer and consumer.
 * Spring Kafka 4.0+ uses auto-configuration via application.yaml.
 * This config is minimal and lets Spring Boot handle serialization.
 */
@Configuration
public class KafkaConfig {
    // Spring Boot 4.0+ auto-configures Kafka with properties from application.yaml
    // No need for custom ProducerFactory/ConsumerFactory beans
}

package com.pdev.ekyc_service.model;

import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.time.LocalDateTime;

/**
 * Entity representing a KYC session for OTP generation and verification.
 */
@Entity
@Table(name = "kyc_sessions")
@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class KycSession {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private String id;

    @Column(nullable = false)
    private String citizenId;

    @Column(nullable = false, unique = true)
    private String txnId;

    @Column
    private String otpHash;

    @Column
    private String aadhaarNumberEncrypted;

    @Column
    private String demographicDataEncrypted;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private KycStatus status;

    @Column
    private LocalDateTime createdAt;

    @Column
    private LocalDateTime verifiedAt;

    @PrePersist
    protected void onCreate() {
        createdAt = LocalDateTime.now();
    }
}

package com.pdev.ekyc_service.model;

/**
 * Enum representing the status of KYC verification process.
 */
public enum KycStatus {
    PENDING,    // OTP generated, waiting for verification
    VERIFIED,   // OTP verified successfully
    FAILED      // OTP verification failed
}

