package com.pdev.citizen_service.dto;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Standard wrapper for ALL API responses.
 * Ensures consistent JSON structure across the service.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class ApiResponse<T> {
    private boolean success;
    private String message;
    private T data;
}

package com.pdev.citizen_service.exception;

/**
 * Exception thrown when KYC verification is required but not completed.
 */
public class KycNotVerifiedException extends RuntimeException {

    public KycNotVerifiedException(String message) {
        super(message);
    }

    public KycNotVerifiedException(String message, Throwable cause) {
        super(message, cause);
    }
}

package com.pdev.ekyc_service.dto;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Standard wrapper for ALL API responses.
 * Ensures consistent JSON structure across the service.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class ApiResponse<T> {
    private boolean success;
    private String message;
    private T data;

    // Explicit constructors for common cases
    public ApiResponse(boolean success, String message) {
        this.success = success;
        this.message = message;
        this.data = null;
    }
}

